        /// <summary>1夸奖/2鞭策/3嘲讽</summary>
        public int Band;

        /// <summary>0共用/1六章/2无尽</summary>
        public int Mode;

        /// <summary>正式差分素材编号</summary>
        public int Expression;

        /// <summary>互动台词（纯文本）</summary>
        public string Text;

        /// <summary>显示秒数，0用默认</summary>
        public float Duration;

        /// <summary>抽选权重，正整数</summary>
        public int Weight;
    }
}
